#include <stdio.h>

int main(void) {
    double a, b; char op;
    if (scanf("%lf %c %lf", &a, &op, &b) != 3) return 1;
    switch (op) {
        case '+': printf("%.2f\n", a + b); break;
        case '-': printf("%.2f\n", a - b); break;
        case '*': printf("%.2f\n", a * b); break;
        case '/':
            if (b == 0.0) printf("除数不能为 0\n");
            else printf("%.2f\n", a / b);
            break;
        default: printf("不支持的运算符\n"); break;
    }
    return 0;
}

