#include <stdio.h>
#include <math.h>

int is_prime(int n) {
    if (n < 2) return 0;
    for (int i = 2; i <= (int)sqrt((double)n); i++)
        if (n % i == 0) return 0;
    return 1;
}

int main(void) {
    for (int n = 2; n <= 30; n++)
        if (is_prime(n)) printf("%d ", n);
    printf("\n");
    return 0;
}

