#include <stdio.h>

void bubble(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int sw = 0;
        for (int j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j+1]) { int t=a[j]; a[j]=a[j+1]; a[j+1]=t; sw=1; }
        if (!sw) break;
    }
}

int bsearch_(int a[], int n, int x) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == x) return mid;
        if (a[mid] < x) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}

int main(void) {
    int a[] = {42, 7, 19, 88, 3};
    int n = sizeof(a)/sizeof(a[0]);
    bubble(a, n);
    printf("idx of 19: %d\n", bsearch_(a, n, 19));
    return 0;
}

