#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node *next; } Node;

Node *push_back(Node *head, int v) {
    Node *p = malloc(sizeof(Node));
    if (!p) return head;
    p->data = v; p->next = NULL;
    if (!head) return p;
    Node *cur = head;
    while (cur->next) cur = cur->next;
    cur->next = p;
    return head;
}

void show(Node *h) { for (Node *p=h;p;p=p->next) printf("%d -> ", p->data); printf("NULL\n"); }

void free_all(Node *h) { while (h) { Node *n=h->next; free(h); h=n; } }

int main(void) {
    Node *head = NULL;
    for (int i=1;i<=5;i++) head = push_back(head, i);
    show(head);
    free_all(head);
    return 0;
}
